y=np.log(-r)
# additive model in log: basis in t and A (polynomials/log)
def basis(t,A,dt=5,dA=5):
    cols=[np.ones_like(t)]
    for i in range(1,dt+1): cols.append(np.log(t)**i)
    for j in range(1,dA+1): cols.append(np.log(A)**j)
    return np.column_stack(cols)
for dt,dA in [(3,3),(5,5),(6,6)]:
